  k=replacements.get(n,n);chosen=json.loads((src/f'm{k:02}.json').read_text());raw[id]=chosen;a=chosen['record']['imageinfo'][0];meta=a['extmetadata'];b=(src/f'm{k:02}.img').read_bytes();path=dest/(id+('.png' if b.startswith(b'\x89PNG') else '.jpg'));path.write_bytes(b);credit=clean(meta.get('Artist',{}).get('value','')) or chosen['record']['title'][5:];url=a['descriptionurl'];license=clean(meta['LicenseShortName']['value']);lu=meta.get('LicenseUrl',{}).get('value','') or (url+'#Licensing' if license=='Attribution' else 'https://creativecommons.org/publicdomain/mark/1.0/');date=clean(meta.get('DateTimeOriginal',{}).get('value','')) or '来源未注明';download=chosen['downloadUrl'];assert not meta.get('Restrictions',{}).get('value'),(id,'restrictions')
